	&= \mathbf{E}[(\b{y}-\b{A}^{(t)}\hat{\b{x}}) (\b{y}-\b{A}^{(t)}\hat{\b{x}})^\top\mathbbm{1}_{\mathcal{F}_{\b{x}^*}}] +\mathbf{E}[(\b{y}-\b{A}^{(t)}\hat{\b{x}}) (\b{y}-\b{A}^{(t)}\hat{\b{x}})^\top\mathbbm{1}_{\bar{\mathcal{F}}_{x^*}}], \\
	&= \mathbf{E}[(\b{y}-\b{A}^{(t)}\hat{\b{x}}) (\b{y}-\b{A}^{(t)}\hat{\b{x}})^\top\mathbbm{1}_{\mathcal{F}_{x^*}}] \pm \gamma.
	\end{align*}

Here, \[\gamma\] is small. Under the event \[\mathcal{F}_{x^*}\], \[\hat{\b{x}}\] has the correct signed-support. Again, since \[\mathbbm{1}_{\mathcal{F}_{\b{x}^*}} = \mathbf{1} - \mathbbm{1}_{\bar{\mathcal{F}}_{\b{x}^*}}\],
	\begin{align*}
	\mathbf{E}[(\b{y}-\b{A}^{(t)}\hat{\b{x}}) (\b{y}-\b{A}^{(t)}\hat{\b{x}})^\top] &= \mathbf{E}[(\b{y}-\b{A}^{(t)}\hat{\b{x}}) (\b{y}-\b{A}^{(t)}\hat{\b{x}})^\top(\mathbf{1} - \mathbbm{1}_{\bar{\mathcal{F}}_{x^*}})] \pm \gamma,\\
	&= \mathbf{E}[(\b{y}-\b{A}^{(t)}\hat{\b{x}}) (\b{y}-\b{A}^{(t)}\hat{\b{x}})^\top] \pm \gamma.
	\end{align*}

Now, using Lemma~\ref{iht:R_th_term} with probability at least \[(1-\delta_{{\c{T}}}^{(t)} - \delta_{\beta}^{(t)})\], \[\hat{\b{x}}_S\] admits the following expression
