	\b{E}[(\b{y} &- \b{A}^{(t)}\hat{\b{x}})(\b{y} - \b{A}^{(t)}\hat{\b{x}})^\top] \\
	&= \b{E}[((\b{A}^*_S  - \b{A}^{(t)}_S(\b{I} - \Lambda^{(t)}_S))\b{x}^*_S  - \b{A}^{(t)}_S\vartheta^{(R)}_S)((\b{A}^*_S  - \b{A}^{(t)}_S(\b{I} - \Lambda^{(t)}_S))\b{x}^*_S  - \b{A}^{(t)}_S\vartheta^{(R)}_S)^\top].

	\end{align*}

Now consider each term of equation \eqref{iht:mat_W_var_term_1}. First, since
	\begin{align*}
