Let \[x \sim {\rm subGaussian}(\sigma^2)\]. Then, for any \[t>0\], it holds that
	\begin{align*}
	\b{Pr}[|x| > t] \leq 2\exp\big(\tfrac{t^2}{2\sigma^2}\big).
	\end{align*}

Consider a finite sequence {\[\b{W}_k \in \mathbb{R}^{n \times m} \]} of independent, random, centered matrices with dimension \[n\]. Assume that each random matrix satisfies \[\b{E}[\b{W}_k] = 0\] and \[\|\b{W}_k\| \leq R\] almost surely. Then, for all \[t\geq 0\],
\begin{align*}
\b{Pr}\big\{ \|\textstyle\sum\limits_{k} \b{W}_k\| \geq t\big\} \leq (n+m) {\rm exp}\big( \tfrac{-t^2/2}{\sigma^2 + Rt/3}\big),
\end{align*}
where \[\sigma^2 := \max\{\|\textstyle\sum\limits_{k} \b{E}[\b{W}_k\b{W}_k^\top]\|, \|\textstyle\sum\limits_{k} \b{E}[\b{W}_k^\top \b{W}_k]\|\}\]. 

Furthermore,
\begin{align*}
\b{E}[\|\textstyle\sum\limits_{k} \b{W}_k\|] \leq \sqrt{2 \sigma^2 \log(n+m)} + \tfrac{1}{3}R\log(n+m).
\end{align*}

Consider a finite sequence {\[\b{w}_k \in \mathbb{R}^{n} \]} of independent, random, zero mean vectors with dimension \[n\]. Assume that each random vector satisfies \[\b{E}[\b{w}_k] = 0\] and \[\|\b{w}_k\| \leq R\] almost surely. Then, for all \[t\geq 0\],
	\begin{align*}
	\b{Pr}\big\{ \|\textstyle\sum\limits_{k} \b{w}_k\| \geq t\big\} \leq 2n {\rm exp}\big( \tfrac{-t^2/2}{\sigma^2 + Rt/3}\big),
	\end{align*}
	where \[\sigma^2 := \|\textstyle\sum\limits_{k} \b{E}[\|\b{w}_k\|^2]\|\]. 
	Furthermore,
	\begin{align*}
	\b{E}[\|\textstyle\sum\limits_{k} \b{w}_k\|] \leq \sqrt{2 \sigma^2 \log(2n)} + \tfrac{1}{3}R\log(2n).
	\end{align*}

\textbf{Chernoff Bound for sub-Gaussian Random Variables} Let \[w\] be an independent sub-Gaussian random variables with variance parameter \[\sigma^2\], then for any \[t>0\] it holds that
	\begin{align*}
	\b{Pr}[|w|>t] \leq 2{\rm exp}(-\tfrac{t^2}{2\sigma^2}).
	\end{align*}

Let \[\b{M} \in \mathbb{R}^{n \times m}\] be a fixed matrix. Let \[\b{w}\] be a vector of independent, sub-Gaussian random variables with mean zero and variance one. Then, for an absolute constant \[c\],
	\begin{align*}
	\b{Pr}[\|\b{M}\b{x}\|_2 - \|\b{M}\|_F> t] \leq {\rm exp}(-\tfrac{ct^2}{\|\b{M}\|^2}).
	\end{align*}

Suppose that the distribution of \[\b{Z}\] satisfies \[\b{Pr}[\|\b{Z}\|\geq L(\log(1/\rho))^C] \leq \rho]\] for some constant \[C>0\], then 
\begin{enumerate}
	\item If \[p = n^{\mathcal{O}(1)}\] then \[\|\b{Z}^{(j)}\| \leq \tilde{\mathcal{O}}(L)\] holds for each \[j\]  with probability at least\[(1 - \rho)\] and,
	\item \[\|\b{E}[\b{Z}\mathbbm{1}_{\|\b{Z}\|\geq \tilde{\Omega}(L)}]\| = n^{- \omega(1)}\].
\end{enumerate}
In particular, if \[\tfrac{1}{p}\sum_{j =1}^{p} \b{Z}^{(j)} (1 - \mathbbm{1}_{\|\b{Z}\|\geq \tilde{\Omega}(L)})\] is concentrated with probability \[( 1- \rho)\], then so is \[\tfrac{1}{p}\sum_{j = 1}^{p}\b{Z}^{(j)}\].

Suppose random vector \[\b{g}^{(t)}\] is a \[(\rho_{\_}, \rho_{_+}, \zeta_t)\]-correlated with high probability with \[\b{z}^*\] for \[t \in [T] \] where \[T \leq poly(n)\], and \[\eta_A\] satisfies \[0 < \eta_A \leq 2\rho_{_+}\], then for any \[t \in [T]\], 
	\begin{align*}
	\b{E}[\|\b{z}^{(t+1)}- \b{z}^*\|^2] \leq (1 - 2\rho_{\_}\eta_A)\|\b{z}^{(t)} - \b{z}^*\| + 2\eta_A \zeta_t.
	\end{align*}

	In particular, if \[\|\b{z}^{(0)} - \b{z}^*\| \leq  \epsilon_0 \] and \[ \zeta_t \leq (\rho_{\_})o((1 - 2\rho_{\_}\eta)^t) \epsilon_0^2 +  \zeta\], where \[ \zeta = {\max}_{t \in [T]}  \zeta_t\], then the updates converge to \[\b{z}^*\] geometrically with systematic error \[ \zeta/\rho_{\_}\] in the sense that
	\begin{align*}
	\b{E}[\|\b{z}^{(t+1)} - \b{z}^*\|^2] \leq (1 - 2\rho_{\_}\eta_A)^t\epsilon_0^2 +  \zeta/\rho_{\_}. 
	\end{align*}
